('a2a606ff-d0ed-5599-9f09-b819ebdcacd7'::uuid, 'Ormoc City Local Climate Change Action Plan 2019-2030', 'plan', null, null, 'City Government of Ormoc', null::date, 'LCCAP with climate projections (RCP 8.5), a CDRA (HLURB method) with flood, landslide, storm-surge, earthquake, liquefaction and tsunami maps, the first GHG inventory (2017), decision areas and PPAs. Uses the pre-2022 barangay base; predates the 2023 CDRA and the DRRM 10-Year Plan.', array['A3.2','A4.7','A5.1','A5.2','C1.1','C1.3','C3.1','C3.3','C4.3']::text[], 'https://drive.google.com/file/d/17yGyM-JS6oKPHddsv0tpYrcNtKO2WIGp/view', 'Project Drive (CDRRMO folder)', 'current', 'standard', array[]::public.app_role[]),
('9c85480e-a212-5257-b118-1f9d0698df10'::uuid, 'Comprehensive Development Plan 2024-2030, Part 1: Ecological Profile 2022', 'plan', null, 'Vol. 1', 'City Planning and Development Office', null::date, 'City profile with hazard maps (flood, landslide, ground shaking, liquefaction, rain-induced landslide, storm surge) and the 2022 merger of the 28 district barangays into South, East and West, with District 29 renamed North (85 barangays).', array['A5.1','A5.3']::text[], 'https://drive.google.com/file/d/1PPGKRK_faECiOA1DGj1_qYCYZtwfU39o/view', 'Project Drive (CDRRMO folder)', 'current', 'standard', array[]::public.app_role[]),
