('f2e38295-9a71-52e7-8dba-03b86ed3b3c5'::uuid, 'CDRRMC Resolution No. 01, s. 2025: approving the LDRRMIP Trust Fund for CY 2025 (PHP 52,713,712.18)', 'city_issuance', null, 'CDRRMC Res. No. 01, s. 2025', 'City DRRM Council', '2025-06-26'::date, '2nd Quarter meeting. Approves the CY 2025 Trust Fund investment plan and transmits it to the SP for approval.', array['A3.5','A4.3']::text[], 'https://drive.google.com/file/d/1Ow0RaKQGC67ZL2eykpvy-CpxH6EJP7TY/view', 'Project Drive (CDRRMO folder); scanned copy, text read by OCR', 'current', 'standard', array[]::public.app_role[]),
('7b022cf2-9c7f-596b-954c-e8df66743984'::uuid, 'CDRRMC Resolution No. 02, s. 2025: support for July as National Disaster Resilience Month', 'city_issuance', null, 'CDRRMC Res. No. 02, s. 2025', 'City DRRM Council', '2025-06-26'::date, 'Commits the City to the observance under RDRRMC VIII Memo No. 06-007, s. 2025.', array['A1.3','A6.6']::text[], 'https://drive.google.com/file/d/1Kj-tQQs0GnuL1eaX-Go_DBqOyBZvv1Ou/view', 'Project Drive (CDRRMO folder); scanned copy, text read by OCR', 'current', 'standard', array[]::public.app_role[]),
('c8f3dc4f-b3d3-57db-b472-73d62cbffdc8'::uuid, 'CDRRMC Resolution No. 03, s. 2025: support and adoption of Proclamation No. 920 (State of Calamity, Region VIII)', 'city_issuance', null, 'CDRRMC Res. No. 03, s. 2025', 'City DRRM Council', '2025-06-26'::date, 'Adopts the regional State of Calamity declared over the San Juanico Bridge load restriction. Example of how a national proclamation is read locally.', array['A1.6']::text[], 'https://drive.google.com/file/d/1s10x7KB-RfsTSm3gK7hhdnb-N5tgcra9/view', 'Project Drive (CDRRMO folder); scanned copy, text read by OCR', 'current', 'standard', array[]::public.app_role[]),
