('d8ce6a10-0724-5034-8d89-65af924ede83'::uuid, 'CDRRMC Resolution No. 06, s. 2025: use of PHP 2,000,000 of the 30% QRF for food and non-food items, Typhoon Tino (Kalmaegi)', 'city_issuance', null, 'CDRRMC Res. No. 06, s. 2025', 'City DRRM Council', '2025-11-08'::date, 'Special meeting. Augments CSWD relief operations. Does not cite the State of Calamity declaration relied on for QRF use.', array['A1.6','A4.4','A7.5']::text[], 'https://drive.google.com/file/d/1fEQEOZuOchZordgIJsIw1sicMdDKiPqH/view', 'Project Drive (CDRRMO folder); scanned copy, text read by OCR', 'current', 'standard', array[]::public.app_role[]),
('86595062-2437-5161-a6fb-78cc9d5383c2'::uuid, 'CDRRMC Resolution No. 07, s. 2025: supplemental appropriation of PHP 493,550.11 to the 2025 LDRRMF', 'city_issuance', null, 'CDRRMC Res. No. 07, s. 2025', 'City DRRM Council', '2025-11-20'::date, 'Share from unappropriated situs of taxation, split 30% QRF and 70% mitigation and preparedness, as required by the SP Committee on Finance. The copy has no secretariat certification.', array['A4.2']::text[], 'https://drive.google.com/file/d/1mcxM7jRKB0jNfGvBuOuNbCCbPRDxDV6W/view', 'Project Drive (CDRRMO folder); scanned copy, text read by OCR', 'current', 'standard', array[]::public.app_role[]),
('1b8457f5-31e6-51b9-95bc-56023942bb1b'::uuid, 'CDRRMC Resolution No. 08, s. 2025: reallocation of PHP 2,000,000 of the 2025 LDRRMIP Trust Fund to drainage works, Malacadios St., Barangay South', 'city_issuance', null, 'CDRRMC Res. No. 08, s. 2025', 'City DRRM Council', '2025-11-20'::date, 'Flood-mitigation project endorsed to the SP after City Accountant advice that reallocation needs CDRRMC approval and SP concurrence. The copy has no secretariat certification.', array['A4.3','C3.3']::text[], 'https://drive.google.com/file/d/1NZYIr1s1uCvVPDK3aTONE8NObEJeLWxL/view', 'Project Drive (CDRRMO folder); scanned copy, text read by OCR', 'current', 'standard', array[]::public.app_role[]),
('8a31cb24-5396-5ffa-831b-b79b78195140'::uuid, 'CDRRMC Resolution No. 09, s. 2024: adopting the Incident Command System as the standard management system for planned and unplanned events', 'city_issuance', null, 'CDRRMC Res. No. 09, s. 2024', 'City DRRM Council', '2024-11-29'::date, 'Directs the CDRRMO to train city and barangay officials and responders on ICS, build ICS into plans and drills, and evaluate its use. No implementing EO yet.', array['A2.6','A8.1','B6.1','B7.2']::text[], 'https://drive.google.com/file/d/1YcmUc6qCCikvloVTApBOfy4on8VcJPVg/view', 'Project Drive (CDRRMO folder); scanned copy, text read by OCR', 'current', 'standard', array[]::public.app_role[]),
('4fdb7caf-61fe-5c60-a8ce-2c9212bf47ef'::uuid, 'CDRRMC Resolution No. 10, s. 2024: recommending the City College of Ormoc as a regular CDRRMC member', 'city_issuance', null, 'CDRRMC Res. No. 10, s. 2024', 'City DRRM Council', '2024-11-29'::date, '4th Quarter meeting. Recommendation to the Mayor; no amending EO found.', array['A1.2']::text[], 'https://drive.google.com/file/d/1XVd5yauq78ZLaGjYvZtdcssAMSBTy7f4/view', 'Project Drive (CDRRMO folder); scanned copy, text read by OCR', 'current', 'standard', array[]::public.app_role[]),
