('ec3c5691-fb6b-5fcc-82ac-8678ef32a28c'::uuid, 'Executive Order No. 2023-0085: creating the Barangay DRRM Plan Review Team', 'city_issuance', null, 'EO No. 2023-0085', 'Office of the City Mayor', '2023-12-29'::date, 'CDRRMO-led team reviews barangay DRRM plans against the Enhanced QAS for BDRRMP/C (NDRRMC MC 03 s. 2022), issues Certificates of Review and copies DILG within 3 days.', array['A3.7','A7.3']::text[], 'https://drive.google.com/file/d/1ju-lZG547JXk-UYhR78aCZ9Dg_gpR3MJ/view', 'Project Drive (CDRRMO folder); scanned copy, text read by OCR', 'current', 'standard', array[]::public.app_role[]),
